  toggle() {
    this.open = !this.open;
    if (this.open) {
      const trigger = this.$el.querySelector('[data-slot=&#34;dropdown-menu-trigger&#34;]');
      const content = this.$el.querySelector('[data-slot=&#34;dropdown-menu-content&#34;]');
      if (trigger &#38;&#38; content) {
        content.style.setProperty('--anchor-width', trigger.offsetWidth + 'px');
      }
    }
  },

  close() {
    this.open = false;
    this.highlightedIndex = -1;
    this.$el.querySelector('[data-slot=&#34;dropdown-menu-trigger&#34;]')?.focus();
  },

  initHighlight() {
    const activeIndex = this.items.findIndex(item => item.el.hasAttribute('data-active'));
    this.highlightedIndex = activeIndex >= 0 ? activeIndex : 0;
    this.$nextTick(() => this.scrollToHighlighted());
  },

  highlightNext() {
    if (this.highlightedIndex < this.items.length - 1) {
      this.highlightedIndex++;
      this.scrollToHighlighted();
    }
  },

  highlightPrev() {
    if (this.highlightedIndex > 0) {
      this.highlightedIndex--;
      this.scrollToHighlighted();
    }
  },

  highlightFirst() {
    this.highlightedIndex = 0;
    this.scrollToHighlighted();
  },

  highlightLast() {
    this.highlightedIndex = this.items.length - 1;
    this.scrollToHighlighted();
  },

  scrollToHighlighted() {
    const item = this.items[this.highlightedIndex];
    if (item?.el) {
      item.el.scrollIntoView({ block: 'nearest' });
      item.el.focus();
    }
  },

  typeAhead(char) {
    this.searchQuery += char.toLowerCase();
    clearTimeout(this.searchTimeout);
    this.searchTimeout = setTimeout(() => { this.searchQuery = ''; }, 500);
    const match = this.items.findIndex(item =>
      item.label.toLowerCase().startsWith(this.searchQuery)
    );
    if (match >= 0) {
      this.highlightedIndex = match;
      this.scrollToHighlighted();
    }
  }
