    this.items = Array.from(
      this.$el.querySelectorAll('[data-slot=&#34;dropdown-menu-item&#34;]:not([data-disabled])')
    ).map((el, index) => ({
      el,
      label: el.dataset.label || el.textContent?.trim() || '',
