import json

with open('wb_growth.json', 'r') as f:
    data = json.load(f)

# Country code mapping to name
countries = {}
growth_data = {}

for series in data[1]:
    country_code = series['countryiso3code']
    country_name = series['country']['value']
    year = int(series['date'])
    value = series['value']

    if country_code not in growth_data:
        growth_data[country_code] = {'name': country_name, 'years': {}}

    growth_data[country_code]['years'][year] = value

# Now filter based on the criteria
valid_countries = []
for code, info in growth_data.items():
    if not info['years'] or len(info['years']) < (2020-2012+1):
        continue

    valid = True
    for y in range(2012, 2021):
        v = info['years'].get(y)
        if v is None or v < 1.5:
            valid = False
            break

    if valid:
        valid_countries.append(info['name'])

print("Countries with growth > 1.5% from 2012 to 2020:")
print(valid_countries)
