cat << 'EOF' > process_gdp.py
import json

with open('wb_growth.json', 'r') as f:
    data_growth = json.load(f)
with open('wb_gdp_share.json', 'r') as f:
    data_gdp = json.load(f)

growth_data = {}
gdp_data = {}

for series in data_growth[1]:
    country_code = series['countryiso3code']
    country_name = series['country']['value']
    year = int(series['date'])
    value = series['value']

    if country_code not in growth_data:
        growth_data[country_code] = {'name': country_name, 'years': {}}

    growth_data[country_code]['years'][year] = value

for series in data_gdp[1]:
    country_code = series['countryiso3code']
    value = series['value']

    if country_code == 'WLD':
        world_gdp = value

    gdp_data[country_code] = value

# Now filter based on the criteria
valid_countries = []
for code, info in growth_data.items():
    if not info['years'] or len(info['years']) < (2020-2012+1):
        continue

    valid = True
    for y in range(2012, 2021):
        v = info['years'].get(y)
        if v is None or v < 1.5:
            valid = False
            break

    if valid:
        # Check share of > 0.1% of world GDP
        if code in gdp_data and gdp_data[code] is not None and world_gdp is not None:
             share = (gdp_data[code] / world_gdp) * 100
             if share >= 0.1:
                 valid_countries.append(info['name'])

print("Countries with growth > 1.5% from 2012 to 2020 and > 0.1% GDP share in 2023:")
print(valid_countries)
EOF
python3 process_gdp.py
